import { createRoot } from 'react-dom/client';
import { Provider } from 'react-redux';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { store } from '../../src/store';
import { loginSuccess } from '../../src/store/slices/authSlice';
import { AdminLiveManagement } from '../../src/pages/admin/AdminLiveManagement';
import { TemplatePreviewPage } from '../../src/pages/TemplatePreviewPage';
import { ProtectedRoute } from '../../src/router/ProtectedRoute';
import { CustomerChangePassword } from '../../src/pages/auth/CustomerChangePassword';
import { AdminPreviewPage } from '../../src/pages/admin/AdminPreviewPage';
import { PageTemplateLibrary } from '../../src/pages/PageTemplateLibrary';
import { BookingTemplates } from '../../src/pages/booking/BookingTemplates';
import { ProductTemplateLibrary } from '../../src/pages/commerce/ProductTemplateLibrary';
import { createPageAsset } from '../../src/pages/page-templates';
import i18n from '../../src/i18n/i18n';
(window as any).__setTemplateLanguage = (language: string) => i18n.changeLanguage(language);
import '../../src/index.css';
import '../../src/pages/admin/admin-workspace.css';
import '../../src/components/layout/super-admin.css';
const params = new URLSearchParams(location.search), view = params.get('view') || 'admin';
store.dispatch(loginSuccess({ user: { id: 'fixture', name: 'Fixture', email: 'fixture@example.com', ...(view === 'password' ? { requiresPasswordChange: true } : {}) }, tenant: { id: 'fixture', name: 'Fixture workspace' }, role: view === 'password' ? 'CUSTOMER' : view === 'admin' || location.pathname === '/admin-preview' ? 'SUPER_ADMIN' : 'USER', token: 'fixture' }));
if (params.get('theme') === 'dark') document.documentElement.classList.add('dark');
createRoot(document.getElementById('root')!).render(<Provider store={store}><MemoryRouter initialEntries={[view === "password" ? "/portal/paid-course" : location.pathname + location.search]}><Routes><Route path="/portal/:id" element={<ProtectedRoute allowedRoles={["CUSTOMER"]}><h1>Purchase delivery</h1></ProtectedRoute>}/><Route path="/customer/change-password" element={<ProtectedRoute allowedRoles={["CUSTOMER"]} allowPendingPassword><CustomerChangePassword/></ProtectedRoute>}/><Route path="/admin-preview" element={<AdminPreviewPage/>}/><Route path="/template-preview/:templateId" element={<TemplatePreviewPage/>}/><Route path="*" element={view === 'admin' ? <div className="sa-shell"><main className="sa-main"><div className="sa-content"><div className="adm-shell sa-templates"><AdminLiveManagement moduleId="templates"/></div></div></main></div> : view === 'booking' ? <BookingTemplates/> : view === 'products' ? <ProductTemplateLibrary/> : <main className="aw-workspace" style={{ padding: 24 }}><PageTemplateLibrary install={template => { (window as any).__installedPage = createPageAsset(template.mode, template.name, template); }}/></main>}/><Route path="/dashboard/booking/:id/edit" element={<h1>Booking copy created</h1>}/><Route path="/dashboard/products-payments/products/:id/edit" element={<h1>Product copy created</h1>}/></Routes></MemoryRouter></Provider>);
